# nginx in front of the web service (Day 15). Mounted by compose.override.yaml.
server {
    listen 80;

    location / {
        # "web" is the Compose service name. Docker's DNS turns it into an IP.
        proxy_pass http://web:8000;
        proxy_set_header Host $host;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
    }
}
